    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nMap units and recombination frequency calculation.\n\n2. STEP-BY-STEP SOLUTION:\nBy definition, 1 map unit (cM) equals 1% recombination frequency. A distance of 5 cM means that 5% of the test-cross offspring will be recombinants, divided equally between the two recombinant classes (2.5% Ab and 2.5% aB).\n\n3. FINAL ANSWER:\nOption A: 5% of total progeny (2.5% Ab and 2.5% aB)\n\n4. WHY OTHER OPTIONS ARE WRONG:\n95% represents parental combinations (AB and ab).",
